/**
 * Sumber tunggal warna status Stock Out Motor.
 * DISAMAKAN PERSIS dengan Document States (meta.states) doctype "Stock Out Motor"
 * — warna indikator yang dipakai Frappe untuk field workflow `workflow_state`
 * (workflow "Stok Out Motor"). Dipakai untuk pill status di list card portal.
 */

// workflow_state → nama warna Frappe (persis dari Document States doctype).
const STATE_COLOR = {
	Draft: 'yellow',
	'Request Approval': 'cyan',
	Approved: 'blue',
	Rejected: 'pink',
	Cancelled: 'red',
}

// Daftar state urut sesuai alur workflow (Draft → Request Approval → terminal).
// Dipakai sub-sheet filter status (pilih banyak → operator Frappe `in`).
export const STATUS_OPTIONS = ['Draft', 'Request Approval', 'Approved', 'Rejected', 'Cancelled']

// Tebak warna untuk state tak terdaftar — meniru frappe.utils.guess_colour.
function guessColor(status) {
	const s = String(status || '')
	if (/Pending|Menunggu|Request|Review/i.test(s)) return 'orange'
	if (/Reject|Cancel|Failed|Error/i.test(s)) return 'red'
	if (/Approved|Done|Success|Complete/i.test(s)) return 'green'
	if (/Draft|Submitted/i.test(s)) return 'blue'
	return 'gray'
}

export function statusColor(status) {
	return STATE_COLOR[status] || guessColor(status)
}

// Pill (bg + teks) untuk badge status di card.
const PILL = {
	gray: 'bg-ui-surface-gray-100 text-ui-ink-gray-600',
	blue: 'bg-ui-surface-blue-100 text-ui-ink-blue-700',
	cyan: 'bg-ui-surface-cyan-100 text-ui-ink-cyan-700',
	orange: 'bg-ui-surface-orange-100 text-ui-ink-orange-700',
	green: 'bg-ui-surface-green-100 text-ui-ink-green-700',
	red: 'bg-ui-surface-red-100 text-ui-ink-red-700',
	yellow: 'bg-ui-surface-yellow-100 text-ui-ink-yellow-800',
	pink: 'bg-ui-surface-pink-100 text-ui-ink-pink-700',
}
export function statusPillClass(status) {
	return PILL[statusColor(status)] || PILL.gray
}

// Titik (border lingkaran) untuk picker status di sheet filter.
const DOT = {
	gray: 'border-ui-line-gray-400',
	blue: 'border-ui-line-blue-500',
	cyan: 'border-ui-line-cyan-500',
	orange: 'border-ui-line-orange-500',
	green: 'border-ui-line-green-500',
	red: 'border-ui-line-red-500',
	yellow: 'border-ui-line-yellow-500',
	pink: 'border-ui-line-pink-500',
}
export function statusDotClass(status) {
	return DOT[statusColor(status)] || DOT.gray
}

// ---- Filter unit Motor Tarikan per `tipe` ----------------------------------
// PERSIS `frm.set_query("motor_tarikan", "items", ...)` di desk
// (stock_out_motor.js) & aturan validate server (_validate_items_filter):
//   Lelang  : Tarikan + tipe_unit Lelang + Stok AYDA
//   BBG     : Tarikan + tipe_unit BBG + Stok AYDA + dealer cocok
//   Pinjam  : status_unit ∈ (Stok AYDA, Stok Titipan)
//   Titipan : Titipan + Stok Titipan
//   Tebus   : Tarikan + Stok Tebus
// Semua hanya unit submitted (docstatus 1).
export function motorTarikanFiltersByTipe(tipe, idDealer) {
	if (tipe === 'Lelang') {
		return [
			['tipe_motor', '=', 'Tarikan'],
			['tipe_unit', '=', 'Lelang'],
			['status_unit', '=', 'Stok AYDA'],
			['docstatus', '=', 1],
		]
	}
	if (tipe === 'BBG') {
		const f = [
			['tipe_motor', '=', 'Tarikan'],
			['tipe_unit', '=', 'BBG'],
			['status_unit', '=', 'Stok AYDA'],
			['docstatus', '=', 1],
		]
		if (idDealer) f.push(['id_dealer', '=', idDealer])
		return f
	}
	if (tipe === 'Pinjam') {
		return [
			['status_unit', 'in', ['Stok AYDA', 'Stok Titipan']],
			['docstatus', '=', 1],
		]
	}
	if (tipe === 'Titipan') {
		return [
			['tipe_motor', '=', 'Titipan'],
			['status_unit', '=', 'Stok Titipan'],
			['docstatus', '=', 1],
		]
	}
	if (tipe === 'Tebus') {
		return [
			['tipe_motor', '=', 'Tarikan'],
			['status_unit', '=', 'Stok Tebus'],
			['docstatus', '=', 1],
		]
	}
	// Belum pilih tipe → fallback seperti desk.
	return [['docstatus', '=', 1]]
}
